using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.HasIndex(p => p.Sku);
            entity.ToContainer("Products");

            // EF9 changed the default discriminator property from "Discriminator" to "$type".
            // Preserve "Discriminator" so existing 500K documents remain readable and
            // direct SQL queries referencing c.Discriminator continue to work.
            entity.HasDiscriminator<string>("Discriminator");

            // EF9 changed the default id format from "EntityType|Key" to just "Key".
            // Preserve the EF8 format so existing documents (e.g. "Product|123") are found.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id");
            entity.UseETagConcurrency();
        });

        // Preserve EF8-style composite "EntityType|Key" id values for all entities.
        modelBuilder.ConfigureConventions(conventions =>
        {
#pragma warning disable CS0618 // Obsolete API kept intentionally for data compatibility
            conventions.ConfigureId(StoreObjectId.Create);
#pragma warning restore CS0618
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

